import { test, expect, Page } from '@playwright/test';

test.describe('User Logout - Secure Session Termination', () => {
  let page: Page;

  test.beforeEach(async ({ browser }) => {
    page = await browser.newPage();
    await page.goto('http://localhost:3000');

    // Login before each test
    await page.getByLabel('Email').fill('testuser@example.com');
    await page.getByLabel('Password').fill('SecurePassword123!');
    await page.getByRole('button', { name: /sign in/i }).click();

    // Wait for dashboard to load
    await page.waitForURL('**/dashboard');
    await expect(page.getByRole('heading', { name: /dashboard/i })).toBeVisible();
  });

  test('should successfully logout and redirect to login page', async () => {
    // Verify user is logged in
    const userMenu = page.getByRole('button', { name: /account menu/i });
    await expect(userMenu).toBeVisible();

    // Click logout button
    await userMenu.click();
    const logoutButton = page.getByRole('menuitem', { name: /logout/i });
    await logoutButton.click();

    // Verify redirect to login page
    await page.waitForURL('**/login');
    await expect(page.getByRole('heading', { name: /sign in/i })).toBeVisible();

    // Verify login form is displayed
    await expect(page.getByLabel('Email')).toBeVisible();
    await expect(page.getByLabel('Password')).toBeVisible();
  });

  test('should clear session data after logout', async () => {
    // Verify user data is accessible before logout
    const userGreeting = page.getByText(/welcome/i);
    await expect(userGreeting).toBeVisible();

    // Perform logout
    const userMenu = page.getByRole('button', { name: /account menu/i });
    await userMenu.click();
    const logoutButton = page.getByRole('menuitem', { name: /logout/i });
    await logoutButton.click();

    // Wait for redirect
    await page.waitForURL('**/login');

    // Verify session is cleared by checking localStorage
    const sessionToken = await page.evaluate(() => {
      return localStorage.getItem('authToken');
    });
    expect(sessionToken).toBeNull();

    // Verify cannot access protected routes
    await page.goto('http://localhost:3000/dashboard');
    await page.waitForURL('**/login');
    await expect(page.getByRole('heading', { name: /sign in/i })).toBeVisible();
  });

  test('should display logout confirmation message', async () => {
    // Click logout
    const userMenu = page.getByRole('button', { name: /account menu/i });
    await userMenu.click();
    const logoutButton = page.getByRole('menuitem', { name: /logout/i });
    await logoutButton.click();

    // Verify success message appears
    const successMessage = page.getByText(/logged out successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify message disappears after redirect
    await page.waitForURL('**/login');
    await expect(successMessage).not.toBeVisible();
  });

  test('should prevent access to protected resources after logout', async () => {
    // Get current user data endpoint
    const userDataResponse = await page.request.get('http://localhost:3000/api/user');
    expect(userDataResponse.status()).toBe(200);

    // Perform logout
    const userMenu = page.getByRole('button', { name: /account menu/i });
    await userMenu.click();
    const logoutButton = page.getByRole('menuitem', { name: /logout/i });
    await logoutButton.click();

    // Wait for redirect
    await page.waitForURL('**/login');

    // Verify API calls are rejected after logout
    const unauthorizedResponse = await page.request.get('http://localhost:3000/api/user');
    expect(unauthorizedResponse.status()).toBe(401);
  });

  test('should handle logout from different pages', async () => {
    // Navigate to a different protected page
    await page.goto('http://localhost:3000/profile');
    await page.waitForURL('**/profile');

    // Verify user is on profile page
    await expect(page.getByRole('heading', { name: /profile/i })).toBeVisible();

    // Perform logout
    const userMenu = page.getByRole('button', { name: /account menu/i });
    await userMenu.click();
    const logoutButton = page.getByRole('menuitem', { name: /logout/i });
    await logoutButton.click();

    // Verify redirect to login
    await page.waitForURL('**/login');
    await expect(page.getByRole('heading', { name: /sign in/i })).toBeVisible();
  });
});
